/* Installation + offline shell status. Updates never reload an active experiment. */
(()=>{const byId=id=>document.getElementById(id),button=byId('installApp'),note=byId('pwaStatus'),update=byId('updateApp');let installEvent=null,registration=null,reloading=false,requestedUpdate=false;
const standalone=()=>window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
function installed(){button.hidden=true;note.textContent='Installed app'}
function instructions(){if(standalone()){installed();return}let ios=/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);note.textContent=ios?'In Safari, tap Share → Add to Home Screen → Add.':'Open this site in your phone’s browser, then use its menu → Install app or Add to Home screen.'}
button.onclick=async()=>{if(!installEvent){instructions();return}try{await installEvent.prompt();let choice=await installEvent.userChoice;installEvent=null;if(choice.outcome==='accepted'){note.textContent='Installation requested. Your browser will finish setup.';button.hidden=true}else instructions()}catch(e){note.textContent='Install prompt unavailable. Use your browser’s Install app menu.'}};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;if(!standalone()){button.hidden=false;button.textContent='↓ Install app';note.textContent='Install Arcfield on this device.'}});
window.addEventListener('appinstalled',()=>{installEvent=null;installed()});
function offerUpdate(){if(registration?.waiting){update.hidden=false;note.textContent='An app update is ready. Apply it after your current experiment finishes.'}}
update.onclick=()=>{if(typeof worker!=='undefined'&&worker){note.textContent='Finish or cancel the active experiment before updating. Export partial results first if needed.';return}if(!registration?.waiting)return;requestedUpdate=true;registration.waiting.postMessage({type:'ACTIVATE_UPDATE'});update.disabled=true;note.textContent='Applying update…'};
window.addEventListener('online',()=>{note.textContent='Online';registration?.update().catch(()=>{})});window.addEventListener('offline',()=>{note.textContent='Offline · cached app and saved runs remain on this device.'});
if(standalone())installed();
if(!('serviceWorker' in navigator)){note.textContent='Install/offline support is unavailable in this browser.';return}
navigator.serviceWorker.addEventListener('controllerchange',()=>{if(requestedUpdate&&!reloading){reloading=true;window.location.reload()}});
async function register(){try{registration=await navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'});offerUpdate();function watchInstall(incoming){if(!incoming)return;const changed=()=>{if(incoming.state==='installed'){if(navigator.serviceWorker.controller)offerUpdate();else note.textContent='App downloaded · offline support is ready.'}if(incoming.state==='redundant'&&!registration.active)note.textContent='Offline setup did not finish. Reopen online to retry.'};incoming.addEventListener('statechange',changed);changed()}watchInstall(registration.installing);registration.addEventListener('updatefound',()=>watchInstall(registration.installing));navigator.serviceWorker.ready.then(()=>{if(!registration.waiting)note.textContent=standalone()?'Installed · offline-ready':navigator.onLine?'Offline-ready · install from this button or your browser menu.':'Offline-ready · saved runs remain on this device.'});await registration.update()}catch(e){note.textContent=navigator.serviceWorker.controller?'Using cached app · updates will be checked when online.':'Offline setup unavailable: '+e.message+'. The online app still works.'}}
if(document.readyState==='complete')register();else window.addEventListener('load',register,{once:true});})();
